alter policy crowd_demo_read on public.mms_crowd_demo_workspaces using (coalesce((select auth.jwt() ->> 'is_anonymous'), 'false') = 'false' and user_id = (select auth.uid()) and exists (select 1 from public.mms_memberships m where m.user_id = (select auth.uid()) and m.site_id = mms_crowd_demo_workspaces.site_id));
alter policy crowd_demo_insert on public.mms_crowd_demo_workspaces with check (coalesce((select auth.jwt() ->> 'is_anonymous'), 'false') = 'false' and user_id = (select auth.uid()) and exists (select 1 from public.mms_memberships m where m.user_id = (select auth.uid()) and m.site_id = mms_crowd_demo_workspaces.site_id));
alter policy crowd_demo_update on public.mms_crowd_demo_workspaces using (coalesce((select auth.jwt() ->> 'is_anonymous'), 'false') = 'false' and user_id = (select auth.uid()) and exists (select 1 from public.mms_memberships m where m.user_id = (select auth.uid()) and m.site_id = mms_crowd_demo_workspaces.site_id)) with check (coalesce((select auth.jwt() ->> 'is_anonymous'), 'false') = 'false' and user_id = (select auth.uid()) and exists (select 1 from public.mms_memberships m where m.user_id = (select auth.uid()) and m.site_id = mms_crowd_demo_workspaces.site_id));
